mapper.update:
UPDATE afv_canvas SET revision = revision + 1, next_event_sequence = next_event_sequence + 1,
    update_time = UTC_TIMESTAMP(6)
WHERE id = #{id} AND revision = #{revision} AND next_event_sequence = #{sequence}

mapper.select:
SELECT c.*, p.name AS project_name
FROM afv_canvas c LEFT JOIN afv_project p ON p.id = c.project_id AND p.deleted = FALSE
WHERE c.archived = #{archived}
    AND (c.project_id IS NULL
        OR c.project_id IN
            #{project}
        )
    AND (c.created_by = #{userId} OR (c.owner_type = 1 AND c.owner_id = #{userId})
        OR EXISTS (SELECT 1 FROM afv_canvas_member cm WHERE cm.canvas_id = c.id AND cm.user_id = #{userId})
        OR c.project_id IN
            #{project}
        )
    AND (c.project_id IS NULL OR p.id IS NOT NULL)
AND c.project_id = #{projectId}
AND (c.title LIKE #{search} ESCAPE '!' OR p.name LIKE #{search} ESCAPE '!')
ORDER BY c.update_time DESC, c.id
